const $ = (s, root=document) => root.querySelector(s);
const e = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = value => new Intl.NumberFormat(SG.locale(),{style:'currency',currency:'EUR'}).format(Number(value)||0);
const number = value => new Intl.NumberFormat(SG.locale(),{maximumFractionDigits:1}).format(Number(value)||0);
