const icon = (name,cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.grid}</svg>`;
const button = (label,action,attrs='',primary=false,ico='') => `<button class="btn ${primary?'btn-primary':'btn-outline'}" data-action="${action}" ${attrs}>${ico?icon(ico):''}${label}</button>`;
const memberNav=[['dashboard','grid','Visão geral'],['my_plan','spark','My Plan'],['food','camera','Leitor de comida'],['classes','calendar','Aulas de grupo'],['progress','trend','A minha evolução'],['checkin','scan','Check-in digital'],['account','user','Conta e assinatura']];
const communityNav=[['challenges','trophy','Desafios'],['notices','bell','Avisos e novidades'],['support','message','Feedback e suporte']];
const adminNav=[['admin','grid','Visão geral'],['admin-members','users','Membros e planos'],['admin-leads','trend','CRM e leads'],['admin-access','scan','Acessos e lotação'],['admin-staff','users','Equipa e horários'],['admin-classes','calendar','Gestão de aulas'],['admin-reports','chart','Relatórios'],['admin-notices','bell','Comunicação'],['admin-support','message','Pedidos de suporte']];
let state,route='dashboard',selectedDay=today(),calendarStart=today(),classCategory='Todas',classView='agenda',cart=[],exerciseChecks=new Set(),authMode='login',busy=false,toastTimer,pollTimer;
let checkoutKey=crypto.randomUUID();
let installPrompt=null;
window.addEventListener('beforeinstallprompt',ev=>{ev.preventDefault();installPrompt=ev;if(state&&route==='food')render();});
window.addEventListener('appinstalled',()=>{installPrompt=null;toast(SG.L('StrongGym instalada no teu dispositivo.','StrongGym installed on your device.'));});
if('serviceWorker'in navigator&&window.isSecureContext)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
function installButton(cls='nav-link'){return fdIsInstalled()?'':`<button type="button" class="${cls} install-link" data-action="install-help">${icon('download')}${SG.L('Instalar a app','Install the app')}</button>`;}
async function installHelp(){
 if(installPrompt){installPrompt.prompt();const choice=await installPrompt.userChoice;installPrompt=null;if(choice.outcome==='accepted')return;}
 const ios=fdIsIOS(),secure=window.isSecureContext&&!/^(localhost|127\.|\[::1\])/.test(location.hostname);
 const steps=(t,list)=>`<div class="fd-os on"><h3>${icon('phone')} ${t}</h3><ol>${list.map(x=>`<li>${x}</li>`).join('')}</ol></div>`;
 const iosSteps=steps('iPhone / iPad (iOS)',[SG.L('Abre este endereço no <b>Safari</b>.','Open this address in <b>Safari</b>.'),SG.L('Toca em <b>Partilhar</b> (quadrado com seta).','Tap <b>Share</b> (square with an arrow).'),SG.L('Escolhe <b>Adicionar ao ecrã principal</b> → <b>Adicionar</b>.','Choose <b>Add to Home Screen</b> → <b>Add</b>.')]);
 const andSteps=steps('Android',[SG.L('Abre este endereço no <b>Chrome</b>.','Open this address in <b>Chrome</b>.'),SG.L('Toca no menu <b>⋮</b> → <b>Instalar aplicação</b> (ou no aviso <b>Instalar</b>).','Tap the <b>⋮</b> menu → <b>Install app</b> (or the <b>Install</b> banner).'),SG.L('Confirma. A StrongGym fica com ícone próprio.','Confirm. StrongGym gets its own icon.')]);
 modal(SG.L('Instalar a StrongGym','Install StrongGym'),`<div data-no-translate><p class="modal-subtitle">${SG.L('A StrongGym instala-se como uma app, com ícone no ecrã principal, ecrã inteiro e acesso ao leitor de comida.','StrongGym installs like an app, with a home screen icon, full screen and access to the food scanner.')}</p><div class="install-url">${icon('globe')}<b>${e(location.origin+location.pathname)}</b></div><div class="fd-install">${ios?iosSteps+andSteps:andSteps+iosSteps}</div>${secure?'':`<div class="notice-box vertical-space">${icon('info')}<span>${SG.L('Este endereço só funciona neste computador. Para abrir e instalar no telemóvel, usa o endereço público criado pelo <b>Publicar_StrongGym.bat</b>.','This address only works on this computer. To open and install on a phone, use the public address created by <b>Publicar_StrongGym.bat</b>.')}</span></div>`}</div>`);
}
function startLiveReload(){
 if(isDemo||!window.fetch)return;let known=null;
 const check=async()=>{if(document.visibilityState!=='visible')return;try{const r=await fetch('./__version',{cache:'no-store'});if(!r.ok)return;const {version}=await r.json();if(known===null){known=version;return;}if(version!==known){const a=document.activeElement;const typing=a&&/^(INPUT|TEXTAREA|SELECT)$/.test(a.tagName)&&a.value&&a.type!=='checkbox'&&a.type!=='radio';if(typing||$('#modal').open)return;known=version;location.reload();}}catch(_){}};
 check();setInterval(check,2500);
}
function bottomNav(){const items=[['dashboard','grid','Início'],['classes','calendar','Aulas'],['my_plan','spark','My Plan'],['food','camera','Comida']];return `<nav class="bottom-nav" aria-label="Navegação rápida">${items.map(([id,ic,l])=>`<button class="bn-item ${id==='my_plan'?'bn-plan':''} ${route===id?'active':''}" data-route="${id}" ${route===id?'aria-current="page"':''}><span class="bn-icon">${icon(ic)}</span><span>${l}</span></button>`).join('')}<button class="bn-item" data-action="menu"><span class="bn-icon">${icon('menu')}</span><span>Menu</span></button></nav>`;}
const isDemo=window.STRONGGYM_DEMO===true;
const api={
 async request(path,body){const res=await fetch(path,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json','X-CSRF-Token':state?.csrf||''}:{},body:body?JSON.stringify(body):undefined});const data=await res.json();if(!res.ok){const err=new Error(data.error||'Não foi possível concluir o pedido.');err.status=res.status;throw err;}return data;},
 async load(){return isDemo?StrongGymDemo.state():this.request('/api/state');},
 async action(action,payload){return isDemo?StrongGymDemo.action(action,payload):this.request('/api/action',{action,...payload});}
};
function prefToggles(){return `<div class="pref-toggles"><button class="pref-btn lang-btn" data-action="toggle-lang" aria-label="${SG.lang==='en'?'Mudar para português':'Switch to English'}" title="${SG.lang==='en'?'Português':'English'}" data-no-translate>${icon('globe')}<span class="${SG.lang==='pt'?'on':''}">PT</span><span class="${SG.lang==='en'?'on':''}">EN</span></button><button class="icon-btn pref-btn theme-btn" data-action="toggle-theme" aria-label="${SG.theme==='light'?'Modo escuro':'Modo claro'}" title="${SG.theme==='light'?'Modo escuro':'Modo claro'}">${icon(SG.theme==='light'?'moon':'sun')}</button></div>`;}
function rerender(){if(state)render();else renderAuth();}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='visible'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',6500);}
function navigate(to){if(to==='my_plan')MP.step=null;if(location.hash.slice(1)===to){route=to;render();}else location.hash=to;closeModal();window.scrollTo({top:0,behavior:'instant'});}
function resetTransient(){MP.step=null;cart=[];exerciseChecks.clear();checkoutKey=crypto.randomUUID();classView='agenda';classCategory='Todas';calendarStart=today();selectedDay=today();}
function closeModal(){const m=$('#modal');if(m.open)m.close();}
function modal(title,body){const el=$('#modal');el.innerHTML=`<div class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Fechar">${icon('close')}</button></div>${body}`;el.showModal();}
async function mutate(action,payload={},close=true){if(busy)return false;busy=true;try{const result=await api.action(action,payload);state=await api.load();if(close)closeModal();render();toast(result.message||'Guardado com sucesso.');return true;}catch(error){toast(error.message,true);return false;}finally{busy=false;}}
function field(label,name,value='',type='text',attrs='',full=false){return `<label class="field ${full?'full':''}">${label}<input type="${type}" name="${name}" value="${e(value)}" ${attrs}></label>`;}
function selectField(label,name,options,value='',full=false){return `<label class="field ${full?'full':''}">${label}<select name="${name}" required>${options.map(o=>{const v=Array.isArray(o)?o[0]:o,l=Array.isArray(o)?o[1]:o;return `<option value="${e(v)}" ${v===value?'selected':''}>${e(l)}</option>`;}).join('')}</select></label>`;}
function textField(label,name,value='',attrs='',full=true){return `<label class="field ${full?'full':''}">${label}<textarea name="${name}" ${attrs}>${e(value)}</textarea></label>`;}
function form(body,action,label='Guardar',attrs=''){return `<form data-form="${action}" ${attrs}><div class="form-grid">${body}</div><div class="form-actions"><button type="button" class="btn btn-ghost" data-action="close-modal">Cancelar</button><button class="btn btn-primary" type="submit">${label}${icon('arrow')}</button></div></form>`;}
function empty(title,copy,ico='calendar'){return `<div class="empty-state">${icon(ico)}<h3>${title}</h3><p>${copy}</p></div>`;}
function panelTitle(title,sub='',link='',to=''){return `<div class="panel-heading"><div><h2>${title}</h2>${sub?`<p class="panel-subtitle">${sub}</p>`:''}</div>${link?`<button class="link-btn" data-route="${to}">${link}${icon('arrow')}</button>`:''}</div>`;}
function metric(label,value,note,ico,highlight=false){return `<div class="metric-card"><div class="metric-top"><span>${label}</span><span class="metric-icon">${icon(ico)}</span></div><div class="metric-value">${value}</div><div class="metric-note ${highlight?'green':''}">${highlight?icon('trend'):''}${note}</div></div>`;}
function heading(title,sub,actions='',eyebrow='O TEU ESPAÇO. A TUA EVOLUÇÃO.'){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function gymArt(){return `<div class="hero-grid"></div><div class="hero-watermark">STRONGER.</div><svg class="hero-art" viewBox="0 0 580 290" aria-hidden="true"><defs><linearGradient id="plate" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#6c5c70"/><stop offset=".4" stop-color="#29232e"/><stop offset="1" stop-color="#08070b"/></linearGradient><linearGradient id="metal"><stop stop-color="#aaa0aa"/><stop offset=".3" stop-color="#332b39"/><stop offset=".5" stop-color="#a79aa9"/><stop offset="1" stop-color="#2b2431"/></linearGradient><radialGradient id="pinkGlow"><stop stop-color="#ff00ff" stop-opacity=".35"/><stop offset="1" stop-color="#ff00ff" stop-opacity="0"/></radialGradient></defs><ellipse cx="350" cy="220" rx="230" ry="100" fill="url(#pinkGlow)"/><g transform="translate(75 105) rotate(-24 220 60)"><rect x="40" y="56" width="435" height="18" rx="5" fill="url(#metal)"/><rect x="180" y="58" width="125" height="14" fill="#8e7e8d"/><path d="M190 59v12m8-12v12m8-12v12m8-12v12m8-12v12m8-12v12m8-12v12m8-12v12m8-12v12m8-12v12m8-12v12m8-12v12m8-12v12m8-12v12" stroke="#4c3e51"/><g fill="url(#plate)" stroke="#89718e" stroke-width="1.2"><rect x="80" y="6" width="37" height="119" rx="14"/><rect x="106" y="-13" width="43" height="157" rx="18"/><rect x="139" y="-23" width="44" height="177" rx="20"/><rect x="304" y="-23" width="44" height="177" rx="20"/><rect x="338" y="-13" width="43" height="157" rx="18"/><rect x="370" y="6" width="37" height="119" rx="14"/></g><path d="M150-12v153m167-153v153" stroke="#ff67e9" stroke-opacity=".55" stroke-width="2"/><path d="M165 4v45m0 34v45M331 4v45m0 34v45" stroke="#58405c" stroke-width="4" stroke-linecap="round"/></g></svg>`;}
function classSymbol(c){const type=c.category==='Yoga'||c.category==='Pilates'?'yoga':c.category==='Cycling'?'cycling':'';return `<span class="class-symbol ${type}">${icon(type==='yoga'?'heart':type==='cycling'?'bike':'bolt')}</span>`;}
function upcoming(){return state.classes.filter(c=>new Date(c.date+'T'+c.time)>new Date()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));}
function classRow(c){const booked=state.bookings.includes(c.id);return `<div class="class-row">${classSymbol(c)}<div class="class-info"><h3>${e(c.title)}</h3><p>${e(c.trainer)}<span>·</span>${c.duration} min</p></div><div class="class-time">${e(c.time)}<small>${c.date===today()?'Hoje':dateLabel(c.date)}</small></div><button class="btn btn-small ${booked?'':'btn-outline'}" data-action="${booked?'cancel-class':'book-class'}" data-id="${e(c.id)}">${booked?'Reservada':c.booked>=c.capacity?'Esgotada':'Reservar'}</button></div>`;}
function weekDays(){const d=new Date(today()+'T12:00:00');d.setDate(d.getDate()-((d.getDay()+6)%7));return Array.from({length:7},(_,i)=>{const n=new Date(d);n.setDate(n.getDate()+i);return n.toLocaleDateString('en-CA');});}
function weeklyChart(){const days=weekDays(),values=days.map(d=>state.visits.filter(v=>v.date===d).length),max=Math.max(2,...values);return `<div class="activity-chart" role="img" aria-label="Visitas por dia: ${days.map((d,i)=>dateLabel(d)+' '+values[i]).join(', ')}">${days.map((d,i)=>`<div class="bar-column"><span class="bar-value">${values[i]||''}</span><div class="bar ${values[i]?'highlight':''}" style="height:${Math.max(4,values[i]/max*90)}%"></div><span class="bar-label">${['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'][i]}</span></div>`).join('')}</div>`;}
function lineChart(items,key='weight'){const points=items.slice(-8);if(!points.length)return empty('A tua evolução começa aqui','Regista a primeira medição para veres o teu gráfico.','trend');const values=points.map(p=>Number(p[key])),min=Math.min(...values)-.8,max=Math.max(...values)+.8;const coords=points.map((p,i)=>[42+i*(400/Math.max(1,points.length-1)),115-(Number(p[key])-min)/(max-min)*95]);const poly=coords.map(v=>v.join(',')).join(' ');return `<svg class="line-chart" viewBox="0 0 470 155" role="img" aria-label="Evolução: ${points.map(p=>dateLabel(p.date)+' '+p[key]).join(', ')}"><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#ff00ff" stop-opacity=".15"/><stop offset="1" stop-color="#ff00ff" stop-opacity="0"/></linearGradient></defs>${[0,1,2].map(i=>`<line x1="40" y1="${20+i*47}" x2="448" y2="${20+i*47}" stroke="#29232f" stroke-dasharray="3 4"/><text x="0" y="${23+i*47}">${number(max-(max-min)*i/2)}</text>`).join('')}<polygon points="${coords[0][0]},120 ${poly} ${coords.at(-1)[0]},120" fill="url(#chartFill)"/><polyline points="${poly}" fill="none" stroke="#f000f0" stroke-width="2.4" stroke-linejoin="round"/>${coords.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="3" fill="#ff00ff" stroke="#111216" stroke-width="2"/><text x="${p[0]}" y="146" text-anchor="middle">${dateLabel(points[i].date,{day:'numeric',month:'short'})}</text>`).join('')}</svg>`;}
function challengeCount(c){if(c.progress!==undefined)return c.progress;if(c.current!==undefined)return c.current;const dates=c.unit==='treinos'?state.workout.completedDates:state.visits.map(v=>v.date);return new Set(dates.filter(d=>d.startsWith(today().slice(0,7)))).size;}
function ring(c){const n=challengeCount(c);return `<div class="challenge-ring" style="--percent:${Math.min(100,n/c.target*100)}%"><strong>${n}<small>/${c.target}</small></strong></div>`;}
function dashboard(){const u=state.user,plan=state.plans.find(p=>p.id===u.plan)||state.plans[0],last=state.progress.at(-1),first=state.progress[0],challenge=state.challenges.find(c=>c.joined)||state.challenges[0];return `${heading(`Olá, ${e(u.name.split(' ')[0])}<span class="pink">.</span>`,'Cada treino conta. Vamos fazer de hoje um bom dia.',button('Fazer check-in','go-checkin','',true,'scan'),new Date().toLocaleDateString(SG.locale(),{weekday:'long',day:'numeric',month:'long',year:'numeric'}))}<section class="hero"><div class="hero-copy"><div class="eyebrow">${icon('bolt')} MAIS FORTE A CADA DIA</div><h2>O teu próximo nível<br>começa <em>aqui.</em></h2><p>O plano está pronto. A motivação é tua.<br>Constrói hoje a tua melhor versão.</p>${button('Vamos treinar','go-workout','',true,'arrow')}</div>${gymArt()}<span class="hero-bottom-badge">${icon('shield')} STRONGGYM TRAINING CLUB</span></section><div class="metric-grid">${metric('Visitas esta semana',`${state.stats.weeklyVisits}<small> / ${state.stats.weeklyGoal}</small>`,'A tua meta semanal','dumbbell')}${metric('Peso atual',last?`${number(last.weight)} <small>kg</small>`:'—',last&&first?`${number(last.weight-first.weight)} kg desde o primeiro registo`:'Regista a primeira medição','scale')}${metric('Pontos Strong',number(state.stats.points),'O teu esforço vale mais','bolt',true)}${metric('Plano '+e(plan.name),`${money(plan.price).replace('€','')}<small>€ / mês</small>`,'Assinatura ativa','crown')}</div><div class="dashboard-columns"><div class="stack"><section class="panel">${panelTitle('A tua atividade','Consistência que se transforma em resultados.')}<div style="display:flex;justify-content:space-between;align-items:center"><span class="small muted">${dateLabel(weekDays()[0])} — ${dateLabel(weekDays()[6])}</span><span class="chip">Esta semana</span></div>${weeklyChart()}<div class="chart-footer"><span><i class="legend-dot"></i>Visitas ao ginásio</span><strong>${state.stats.weeklyVisits} de ${state.stats.weeklyGoal} visitas</strong></div></section><section class="panel">${panelTitle('A tua evolução','Um passo de cada vez.','Ver progresso','progress')}<div class="progress-info"><strong>${last?number(last.weight):'—'}</strong><span>kg</span>${last&&first?`<span class="chip">${number(last.weight-first.weight)} kg no total</span>`:''}</div>${lineChart(state.progress)}</section></div><div class="stack"><section class="panel">${panelTitle('Encontra a tua próxima aula','Energia em grupo. Resultados individuais.','Ver agenda','classes')}${upcoming().slice(0,3).map(classRow).join('')||empty('Sem aulas agendadas','Volta em breve para consultar a agenda.')}</section>${challenge?`<section class="panel challenge-panel">${panelTitle('O teu próximo desafio','','Ver desafios','challenges')}<div class="challenge-mini">${ring(challenge)}<div class="challenge-copy"><h3>${e(challenge.title)}</h3><p>${challenge.target} ${e(challenge.unit)}. Um mês. Tu consegues.</p><span class="reward">${icon('trophy')} +${challenge.points} pontos ao completar</span></div></div></section>`:''}<section class="panel" style="padding-top:17px;padding-bottom:17px"><div class="status-line">${icon('pin')}<span>StrongGym Lisboa</span><span class="dot" style="margin-left:auto"></span><span>${state.occupancy.current}/${state.occupancy.capacity} pessoas</span></div></section></div></div>`;}
function classesPage(admin=false){const days=Array.from({length:7},(_,i)=>{const d=new Date(calendarStart+'T12:00:00');d.setDate(d.getDate()+i);return d.toLocaleDateString('en-CA');});const categories=['Todas',...new Set(state.classes.map(c=>c.category))];const shown=state.classes.filter(c=>(classView==='bookings'?state.bookings.includes(c.id):c.date===selectedDay)&&(classCategory==='Todas'||c.category===classCategory)).sort((a,b)=>a.time.localeCompare(b.time));return `${heading(admin?'Gestão de aulas':'Encontra o teu ritmo.',admin?'Cria aulas e acompanha as reservas em tempo real.':'A energia do grupo. O teu lugar à espera.',admin?button('Nova aula','new-class','',true,'plus'):button(`As minhas reservas (${state.bookings.length})`,'class-view'))}<div class="agenda-toolbar"><div class="heading-actions"><button class="btn btn-small" data-action="week-prev" aria-label="Semana anterior">←</button><span class="small muted">${dateLabel(days[0])} — ${dateLabel(days[6])}</span><button class="btn btn-small" data-action="week-next" aria-label="Semana seguinte">→</button></div><label class="date-jump">Escolher data<input type="date" id="agenda-date" value="${selectedDay}"></label></div><div class="calendar-days">${days.map(d=>`<button class="day ${selectedDay===d&&classView==='agenda'?'active':''}" data-action="select-day" data-day="${d}"><small>${d===today()?'Hoje':dateLabel(d,{weekday:'short'})}</small><strong>${new Date(d+'T12:00:00').getDate()}</strong><small>${dateLabel(d,{month:'short'})}</small></button>`).join('')}</div><div class="tabs">${categories.map(c=>`<button class="tab ${classCategory===c?'active':''}" data-action="class-filter" data-category="${e(c)}">${e(c)}</button>`).join('')}${classView==='bookings'?'<span class="badge">As minhas reservas</span>':''}</div><div class="classes-grid">${shown.map(c=>{const booked=state.bookings.includes(c.id),past=new Date(c.date+'T'+c.time)<=new Date();return `<article class="class-card"><div class="class-card-top">${classSymbol(c)}<span class="badge ${booked?'success':'neutral'}">${booked?'Lugar reservado':e(c.category)}</span></div><h2>${e(c.title)}</h2><p>Com ${e(c.trainer)}</p><div class="class-details"><span>${icon('calendar')}${dateLabel(c.date,{day:'numeric',month:'long'})}</span><span>${icon('clock')}${e(c.time)} · ${c.duration} minutos</span><span>${icon('pin')}${e(c.room)}</span></div><div class="small muted">${c.booked} / ${c.capacity} lugares reservados</div><div class="capacity"><span style="width:${Math.min(100,c.booked/c.capacity*100)}%"></span></div>${admin?`<div class="small pink" style="margin-top:15px">${Math.max(0,c.capacity-c.booked)} lugares disponíveis</div>`:button(booked?'Cancelar reserva':past?'Aula terminada':c.booked>=c.capacity?'Aula esgotada':'Reservar o meu lugar',booked?'cancel-class':'book-class',`data-id="${e(c.id)}" ${!booked&&(past||c.booked>=c.capacity)?'disabled':''}`,!booked,booked?'close':'plus')}</article>`;}).join('')}</div>${!shown.length?`<section class="panel">${empty('Sem aulas para mostrar',classView==='bookings'?'Ainda não reservaste uma aula. Explora a agenda.':'Experimenta outro dia ou outra modalidade.')}</section>`:''}`;}
function workoutPage(){const w=state.workout,done=w.completedDates.includes(today());return `${heading('O teu treino. O teu foco.','Um plano ajustado aos teus objetivos e ao teu ritmo.')}<section class="workout-banner"><div><span class="badge">PLANO PERSONALIZADO</span><h2>${e(w.title)}</h2><p>${e(w.subtitle)}</p><p style="margin-top:10px;font-size:14px">Preparado por ${e(w.trainer)}</p></div>${button(done?'Treino de hoje concluído':'Concluir treino','finish-workout',done?'disabled':'',true,done?'check':'bolt')}</section><section class="panel">${panelTitle('Um exercício de cada vez',`${w.exercises.length} exercícios · marca cada um à medida que terminas`)}${w.exercises.map((x,i)=>`<div class="exercise-row"><span class="exercise-number">${String(i+1).padStart(2,'0')}</span><div><h3>${e(x.name)}</h3><p>${e(x.sets)} séries × ${e(x.reps)} repetições <span>·</span> ${e(x.rest)} de descanso</p></div><label class="exercise-check"><span>Concluído</span><input type="checkbox" aria-label="Concluir ${e(x.name)}" data-exercise="${i}" ${exerciseChecks.has(i)||done?'checked':''} ${done?'disabled':''}></label></div>`).join('')}<div class="workout-progress"><span style="width:${done?100:exerciseChecks.size/Math.max(1,w.exercises.length)*100}%"></span></div><p class="small muted" style="margin-top:13px">${done?w.exercises.length:exerciseChecks.size} de ${w.exercises.length} exercícios concluídos</p></section><section class="panel vertical-space">${panelTitle('Histórico de treinos')}<div class="tabs" style="margin:0">${w.completedDates.slice().reverse().slice(0,20).map(d=>`<span class="badge success">${icon('check')}${dateLabel(d,{day:'numeric',month:'short',year:'numeric'})}</span>`).join('')||'<p class="small muted">O primeiro treino é o início de tudo.</p>'}</div></section>`;}
function progressPage(){const p=state.progress.at(-1);return `${heading('Vê até onde já chegaste.','Regista, acompanha e celebra cada pequena conquista.',button('Registar métricas','new-progress','',true,'plus'))}<div class="metric-grid" style="grid-template-columns:repeat(3,1fr)">${metric('Peso corporal',p?`${number(p.weight)} <small>kg</small>`:'—','Última medição','scale')}${metric('Massa gorda',p?`${number(p.bodyFat)}<small> %</small>`:'—','Última medição','heart')}${metric('Perímetro abdominal',p?`${number(p.waist)} <small>cm</small>`:'—','Última medição','trend')}</div><section class="panel">${panelTitle('Evolução do peso','As tuas últimas 8 medições')}${lineChart(state.progress)}</section><section class="panel vertical-space">${panelTitle('O teu histórico')}<div class="table-wrap"><table class="data-table"><thead><tr><th>Data</th><th>Peso</th><th>Massa gorda</th><th>Perímetro abdominal</th></tr></thead><tbody>${state.progress.slice().reverse().map(p=>`<tr><td>${dateLabel(p.date,{day:'2-digit',month:'long',year:'numeric'})}</td><td><strong>${number(p.weight)} kg</strong></td><td>${number(p.bodyFat)}%</td><td>${number(p.waist)} cm</td></tr>`).join('')}</tbody></table></div>${!state.progress.length?empty('Ainda sem medições','Adiciona o teu primeiro registo.','scale'):''}</section>`;}
function checkinPage(){const active=state.visits.find(v=>!v.exited);return `${heading('A tua entrada. Simplificada.','Regista a tua presença e acompanha as tuas visitas.')}<div class="two-cols"><section class="panel checkin-card"><span class="badge ${active?'success':'neutral'}">${active?'Estás no ginásio':'Pronto para treinar'}</span><div class="checkin-emblem">${icon(active?'check':'scan')}</div><div class="access-number">SG · ${e(state.user.id.slice(-6).toUpperCase())}</div><h2>${active?'Bom treino, '+e(state.user.name.split(' ')[0])+'!':'Vamos dar o próximo passo?'}</h2><p>${active?'Regista a saída quando terminares o teu treino.':'O teu check-in fica associado à tua conta de membro.'}</p>${button(active?'Registar saída':'Fazer check-in','toggle-checkin','',true,active?'logout':'scan')}<p style="font-size:14px;margin:18px 0 0">Registo digital de presença. Abertura de portas não ligada.</p></section><div class="stack" style="grid-template-columns:1fr"><section class="panel">${panelTitle('Há espaço para o teu próximo nível.','Lotação atual do ginásio')}<div class="progress-info"><strong>${state.occupancy.current}</strong><span>/ ${state.occupancy.capacity} pessoas</span><span class="badge success">${state.occupancy.current<state.occupancy.capacity?'Disponível':'Completo'}</span></div><div class="capacity"><span style="width:${state.occupancy.current/state.occupancy.capacity*100}%"></span></div></section><section class="panel">${panelTitle('As tuas últimas visitas')}${state.visits.slice().sort((a,b)=>b.entered.localeCompare(a.entered)).slice(0,6).map(v=>`<div class="class-row"><span class="class-symbol">${icon('check')}</span><div class="class-info"><h3>${dateLabel(v.date,{day:'numeric',month:'long'})}</h3><p>Entrada ${new Date(v.entered).toLocaleTimeString(SG.locale(),{hour:'2-digit',minute:'2-digit'})}</p></div><span class="badge ${v.exited?'neutral':'success'}">${v.exited?'Concluída':'No ginásio'}</span></div>`).join('')||empty('Ainda sem visitas','Faz o teu primeiro check-in.','scan')}</section></div></div>`;}
function productArt(type){const common='<defs><linearGradient id="productShade" x2="1" y2="1"><stop stop-color="#45404a"/><stop offset="1" stop-color="#141118"/></linearGradient></defs>';const logo='<text x="70" y="79" text-anchor="middle" font-size="10" font-family="Arial" font-style="italic" font-weight="900" fill="#ff00ff">STRONG</text><text x="70" y="88" text-anchor="middle" font-size="5" font-family="Arial" letter-spacing="3" fill="#b79abc">GYM</text>';let art='';if(type==='shirt')art='<path d="m47 24-26 14-12 27 23 12 9-16v63h58V61l9 16 23-12-12-27-26-14c-6 13-30 13-36 0Z" fill="url(#productShade)" stroke="#635369"/><path d="M47 24c3 23 43 23 46 0" fill="none" stroke="#1c121f" stroke-width="6"/>'+logo;else if(type==='bottle')art='<path d="M48 29h44l-5 93H53L48 29Z" fill="url(#productShade)" stroke="#84718b"/><rect x="44" y="23" width="52" height="16" rx="5" fill="#c900cb"/><path d="M56 23v-9h24v9" fill="#3d2341" stroke="#b43ab9"/>'+logo;else if(type==='supplement')art='<rect x="34" y="27" width="72" height="100" rx="12" fill="url(#productShade)" stroke="#65546d"/><rect x="31" y="18" width="78" height="20" rx="5" fill="#27212b" stroke="#53435b"/><path d="M35 48h70v58H35Z" fill="#4b154a"/><text x="70" y="62" text-anchor="middle" fill="#e5badf" font-family="Arial" font-size="6" letter-spacing="2">PERFORMANCE</text><text x="70" y="88" text-anchor="middle" fill="#ff00ff" font-family="Arial" font-weight="900" font-size="21">WHEY</text><text x="70" y="101" text-anchor="middle" fill="#dfb6dc" font-family="Arial" font-size="7">PROTEIN · 900 G</text>';else art='<path d="M40 47 20 62l-9 44c0 15 119 15 119 0l-9-44-20-15H40Z" fill="url(#productShade)" stroke="#5b4a66"/><path d="M44 58V36c0-24 52-24 52 0v22" fill="none" stroke="#635168" stroke-width="8"/><path d="M19 68h102M29 65v42M112 65v42" stroke="#8e437f"/>'+logo;return `<svg viewBox="0 0 140 140" aria-hidden="true">${common}${art}</svg>`;}
function shopPage(){return `${heading('Leva a tua força contigo.','Essenciais para dentro e fora do ginásio.',button(`Carrinho (${cart.reduce((n,x)=>n+x.qty,0)})`,'cart','',true,'bag'))}<div class="notice-box">${icon('info')}<span>Loja em demonstração: podes testar o carrinho e criar encomendas, sem cobrança ou entrega real.</span></div><div class="products-grid">${state.products.map(p=>`<article class="product"><div class="product-art">${productArt(p.icon)}</div><div class="product-info"><span class="eyebrow">${e(p.category)}</span><h3>${e(p.name)}</h3><div class="product-footer"><span class="product-price">${money(p.price)}</span>${button(p.stock?'Adicionar':'Esgotado','add-cart',`data-id="${e(p.id)}" ${p.stock?'':'disabled'}`,false,'plus')}</div><p class="small muted" style="font-size:13px;margin-top:11px">${p.stock} unidades disponíveis</p></div></article>`).join('')}</div><section class="panel vertical-space">${panelTitle('As tuas encomendas','Histórico de compras de demonstração')}${ordersTable(state.orders)}</section>`;}
function ordersTable(orders){return orders.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Encomenda</th><th>Data</th><th>Artigos</th><th>Total</th><th>Estado</th></tr></thead><tbody>${orders.map(o=>`<tr><td>#${e(o.id.slice(-8).toUpperCase())}</td><td>${dateLabel(o.date)}</td><td>${o.items.reduce((n,i)=>n+i.qty,0)}</td><td>${money(o.total)}</td><td><span class="badge neutral">Demonstração</span></td></tr>`).join('')}</tbody></table></div>`:empty('Ainda sem encomendas','Os teus próximos essenciais estão na loja.','bag');}
function accountPage(){const u=state.user;return `${heading('O teu espaço pessoal.','Gere os teus dados e encontra o plano certo para ti.',!isDemo?button('Terminar sessão','logout','',false,'logout'):'')}<section class="panel">${panelTitle('Os teus dados','Mantém os teus contactos atualizados.')}<form data-form="account.update"><div class="form-grid">${field('Nome completo','name',u.name,'text','required maxlength="100"')}${field('Email','email',u.email,'email','disabled')}${field('Telemóvel','phone',u.phone||'','tel','maxlength="30"')}${selectField('O meu objetivo','goal',['Ganhar massa muscular','Perder gordura','Melhorar a forma física','Melhorar a condição física','Bem-estar e mobilidade'],u.goal)}</div><div class="form-actions"><button class="btn btn-primary" type="submit">Guardar alterações${icon('check')}</button></div></form></section><div class="section-header"><h2>O teu plano. À tua medida.</h2><span class="badge">Sem cobranças reais</span></div><div class="plans-grid">${state.plans.slice().sort((a,b)=>a.price-b.price).map(p=>`<article class="plan-card ${p.id===u.plan?'current':''}">${p.id===u.plan?'<span class="badge">Plano atual</span>':''}<h3>${e(p.name)}</h3>${p.appOnly?'<span class="plan-tag">Plano digital · só app</span>':''}<div class="plan-price">${money(p.price)}<span> / mês</span></div><ul>${p.features.map(f=>`<li>${icon('check')}${e(f)}</li>`).join('')}</ul>${button(p.id===u.plan?'O teu plano':'Escolher '+e(p.name),'change-plan',`data-id="${e(p.id)}" ${p.id===u.plan?'disabled':''}`,p.id==='premium')}</article>`).join('')}</div><div class="notice-box vertical-space">${icon('info')}<span>As alterações de assinatura são simuladas. A faturação recorrente, cancelamento com efeitos contratuais e cobranças dependem da ligação a um prestador de pagamentos.</span></div>`;}
function challengesPage(){return `${heading('O esforço merece ser celebrado.','Pequenos desafios. Grandes conquistas. Mais motivação.',`<span class="badge">${icon('bolt')}${state.stats.points} pontos Strong</span>`)}<div class="two-cols">${state.challenges.map(c=>`<article class="panel challenge-large"><span class="badge ${c.joined?'success':'neutral'}">${c.joined?'Desafio ativo':'Aceita o desafio'}</span><h2>${e(c.title)}</h2><p>${e(c.description)}</p>${ring(c)}<div class="small muted">${challengeCount(c)} de ${c.target} ${e(c.unit)} este mês</div><div class="status-line pink" style="margin-top:17px">${icon('trophy')} ${c.points} pontos de recompensa</div>${button(c.joined?challengeCount(c)>=c.target?'Desafio superado':'Vamos continuar':'Participar no desafio',c.joined?(c.unit==='treinos'?'go-workout':'go-checkin'):'join-challenge',`data-id="${e(c.id)}"`,!c.joined,'arrow')}</article>`).join('')}</div><section class="panel vertical-space">${panelTitle('Cada passo conta.','Como conquistar pontos Strong')}<div class="three-cols"><div><h3 class="pink">+25 pontos</h3><p class="small muted" style="margin-top:8px">Por cada dia de presença no ginásio.</p></div><div><h3 class="pink">+50 pontos</h3><p class="small muted" style="margin-top:8px">Por cada treino diário concluído.</p></div><div><h3 class="pink">Pontos extra</h3><p class="small muted" style="margin-top:8px">Ao completar um desafio em que participas.</p></div></div></section>`;}
function noticesPage(admin=false){return `${heading(admin?'A comunidade começa na conversa.':'Em dia com o teu ginásio.',admin?'Publica avisos e mantém todos os membros informados.':'Novidades, atualizações e um pouco de motivação.',admin?button('Publicar aviso','new-notice','',true,'plus'):button('Ativar notificações','enable-notifications','',false,'bell'))}<div class="notice-box">${icon('info')}<span>As notificações do navegador funcionam enquanto a aplicação está aberta e mediante autorização. Envio push com a app fechada ainda não configurado.</span></div><section class="panel">${panelTitle('Mural StrongGym',`${state.notices.length} avisos`)}<div style="display:flex;justify-content:flex-end">${!admin?'<button class="link-btn" data-action="read-notices">Marcar todos como lidos</button>':''}</div>${state.notices.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(n=>`<article class="notice-item"><span class="class-symbol">${icon('bell')}</span><div><h3>${e(n.title)} ${!n.read?'<span class="badge" style="margin-left:8px">Novo</span>':''}</h3><p>${e(n.body)}</p><time datetime="${e(n.date)}">${dateLabel(n.date,{day:'numeric',month:'long',year:'numeric'})}</time></div></article>`).join('')||empty('Tudo em dia','As novidades vão aparecer aqui.','bell')}</section>`;}
function supportPage(admin=false){const tickets=admin?state.admin.tickets:state.tickets;return `${heading(admin?'Estamos aqui para ajudar.':'A tua voz faz a diferença.',admin?'Acompanha e responde aos pedidos dos membros.':'Dúvidas, sugestões ou algo que podemos melhorar?',!admin?button('Novo pedido','new-ticket','',true,'plus'):'')}${tickets.map(t=>`<article class="ticket"><div class="ticket-top"><div><h3>${e(t.subject)}</h3><small>${admin?e(t.name||t.memberName||t.memberId||'Membro')+' · ':''}${dateLabel(t.date)}</small></div><span class="badge ${t.reply?'success':'neutral'}">${t.reply?'Respondido':'Aberto'}</span></div><p>${e(t.message)}</p>${t.reply?`<div class="ticket-reply"><strong>Equipa StrongGym</strong><p>${e(t.reply)}</p></div>`:''}${admin?button(t.reply?'Atualizar resposta':'Responder','reply-ticket',`data-id="${e(t.id)}"`,false,'message'):''}</article>`).join('')||`<section class="panel">${empty('Sem pedidos de suporte',admin?'Quando um membro enviar um pedido, aparece aqui.':'Estamos por aqui quando precisares. Envia-nos uma mensagem.','message')}</section>`}`;}
function adminOverview(){const a=state.admin;return `${heading('Um ginásio. Toda a visão.','O essencial para gerires a StrongGym, num só lugar.',button('Publicar aviso','new-notice','',true,'plus'),'PAINEL DE ADMINISTRAÇÃO')}<div class="metric-grid">${metric('Membros',a.members.filter(m=>m.role!=='admin').length,'Contas registadas','users')}${metric('No ginásio',`${state.occupancy.current}<small> / ${state.occupancy.capacity}</small>`,'Lotação atual','scan')}${metric('Leads em aberto',a.leads.filter(l=>!['Convertido','Perdido'].includes(l.stage)).length,'Oportunidades em acompanhamento','trend')}${metric('Pedidos pendentes',a.tickets.filter(t=>!t.reply).length,'À espera da tua resposta','message')}</div><div class="two-cols"><section class="panel">${panelTitle('Próximas aulas','Agenda e reservas','Gerir aulas','admin-classes')}${upcoming().slice(0,4).map(c=>`<div class="class-row">${classSymbol(c)}<div class="class-info"><h3>${e(c.title)}</h3><p>${dateLabel(c.date)} · ${e(c.time)} · ${e(c.trainer)}</p></div><span class="badge neutral">${c.booked}/${c.capacity}</span></div>`).join('')}</section><section class="panel">${panelTitle('Novas oportunidades','Um primeiro contacto pode mudar tudo.','Abrir CRM','admin-leads')}${a.leads.slice(0,4).map(l=>`<div class="class-row"><span class="avatar">${e(initials(l.name))}</span><div class="class-info"><h3>${e(l.name)}</h3><p>${e(l.interest)}</p></div><span class="badge neutral">${e(l.stage)}</span></div>`).join('')||empty('Sem leads','Adiciona o primeiro contacto.','users')}</section></div><section class="panel vertical-space">${panelTitle('Indicadores de receita','Valores de demonstração — sem pagamentos reais','Ver relatório','admin-reports')}${revenueChart()}</section>`;}
function memberTable(){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Membro</th><th>Plano</th><th>Perfil</th><th>Treino</th></tr></thead><tbody>${state.admin.members.map(m=>`<tr><td><div class="table-avatar"><span class="avatar">${e(initials(m.name))}</span><div><strong>${e(m.name)}</strong><small>${e(m.email)}</small></div></div></td><td>${e(state.plans.find(p=>p.id===m.plan)?.name||m.plan||'—')}</td><td><span class="badge neutral">${m.role==='admin'?'Administrador':'Membro'}</span></td><td>${m.role==='admin'?'—':button('Atribuir plano','assign-plan',`data-id="${e(m.id)}"`,false,'dumbbell')}</td></tr>`).join('')}</tbody></table></div>`;}
function adminMembers(){return `${heading('Conhece quem treina contigo.','Consulta os membros e atribui planos de treino personalizados.')}<section class="panel">${panelTitle('Comunidade StrongGym',`${state.admin.members.length} contas registadas`)}${memberTable()}</section>`;}
function adminLeads(){return `${heading('Do primeiro contacto ao primeiro treino.','Acompanha cada oportunidade, passo a passo.',button('Novo lead','new-lead','',true,'plus'))}<div class="metric-grid">${['Novo','Contactado','Visita marcada','Convertido'].map(s=>metric(s,state.admin.leads.filter(l=>l.stage===s).length,'No teu CRM','users')).join('')}</div><section class="panel">${panelTitle('Contactos e oportunidades','Altera o estado para atualizar o acompanhamento.')}<div class="table-wrap"><table class="data-table"><thead><tr><th>Contacto</th><th>Interesse</th><th>Data</th><th>Estado</th></tr></thead><tbody>${state.admin.leads.map(l=>`<tr><td><strong>${e(l.name)}</strong><div class="small muted" style="font-size:13px;margin-top:5px">${e(l.email)}</div></td><td>${e(l.interest)}</td><td>${dateLabel(l.date)}</td><td><select aria-label="Estado de ${e(l.name)}" data-lead="${e(l.id)}">${['Novo','Contactado','Visita marcada','Convertido','Perdido'].map(s=>`<option ${l.stage===s?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>${!state.admin.leads.length?empty('O teu CRM começa aqui','Adiciona o primeiro contacto.','users'):''}</section>`;}
function adminAccess(){const visits=state.admin.visits||[],active=visits.filter(v=>!v.exited);return `${heading('Sempre a par de quem está dentro.','Acompanha entradas, saídas e lotação do ginásio.')}<section class="panel occupancy-large"><div class="challenge-ring" style="--percent:${state.occupancy.current/state.occupancy.capacity*100}%"><strong>${state.occupancy.current}<small>/${state.occupancy.capacity}</small></strong></div><div><span class="badge success">LOTAÇÃO EM TEMPO REAL</span><h2 style="margin-top:13px">${state.occupancy.capacity-state.occupancy.current} lugares disponíveis</h2><p>As entradas e saídas atualizam a lotação automaticamente.</p><span class="small muted">${isDemo?'Inclui dados ilustrativos da demonstração.':'Presenças registadas pela aplicação.'}</span></div></section><section class="panel vertical-space">${panelTitle('Presenças ativas',`${active.length} entradas registadas nesta aplicação`)}<div class="table-wrap"><table class="data-table"><thead><tr><th>Membro</th><th>Entrada</th><th>Estado</th><th>Ação</th></tr></thead><tbody>${active.map(v=>`<tr><td><strong>${e(v.name||v.memberName||v.memberId||v.user_id)}</strong></td><td>${dateLabel(v.date)} · ${new Date(v.entered).toLocaleTimeString(SG.locale(),{hour:'2-digit',minute:'2-digit'})}</td><td><span class="badge success">No ginásio</span></td><td>${button('Registar saída','admin-exit',`data-id="${e(v.id)}"`,false,'logout')}</td></tr>`).join('')}</tbody></table></div>${!active.length?empty('Sem presenças ativas registadas','Os check-ins dos membros vão aparecer aqui.','scan'):''}</section>`;}
function adminStaff(){return `${heading('A equipa por trás da tua força.','Gere os funcionários e organiza os turnos.',button('Adicionar pessoa','new-staff','',true,'plus'))}<div class="three-cols">${state.admin.staff.map(s=>`<article class="staff-card"><span class="avatar">${e(initials(s.name))}</span><div><h3>${e(s.name)}</h3><p>${e(s.role)}</p><small>${e(s.email)}</small></div></article>`).join('')}</div><section class="panel vertical-space"><div class="panel-heading"><div><h2>Horários da equipa</h2><p class="panel-subtitle">Um turno de cada vez, tudo organizado.</p></div>${button('Novo turno','new-shift','',false,'plus')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Funcionário</th><th>Dia</th><th>Entrada</th><th>Saída</th><th>Duração</th></tr></thead><tbody>${state.admin.shifts.slice().sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start)).map(s=>`<tr><td><strong>${e(state.admin.staff.find(p=>p.id===s.staffId)?.name||s.staffId)}</strong></td><td>${dateLabel(s.date,{day:'numeric',month:'long'})}</td><td>${e(s.start)}</td><td>${e(s.end)}</td><td>${number((Number(s.end.slice(0,2))*60+Number(s.end.slice(3))-Number(s.start.slice(0,2))*60-Number(s.start.slice(3)))/60)} h</td></tr>`).join('')}</tbody></table></div></section>`;}
function revenueChart(){const r=state.admin.revenue||[],max=Math.max(1,...r.map(x=>x.value));return `<div class="activity-chart revenue-chart" role="img" aria-label="Receita de demonstração mensal">${r.map((x,i)=>`<div class="bar-column"><span class="bar-value">${money(x.value)}</span><div class="bar ${i===r.length-1?'highlight':''}" style="height:${Math.max(2,x.value/max*85)}%"></div><span class="bar-label">${e(x.month)}</span></div>`).join('')}</div>`;}
function adminReports(){const total=state.admin.revenue.reduce((n,r)=>n+r.value,0),members=state.admin.members.filter(m=>m.role!=='admin'),converted=state.admin.leads.filter(l=>l.stage==='Convertido').length;return `${heading('Números que ajudam a decidir.','Acompanha os principais indicadores da StrongGym.',button('Exportar CSV','export-report','',false,'download'))}<div class="notice-box">${icon('info')}<span>${isDemo?'Receitas históricas ilustrativas para explorar o painel.':'Os valores apresentados são totais de encomendas simuladas, sem pagamentos reais.'} Este relatório não é um documento contabilístico.</span></div><div class="metric-grid">${metric('Receita de demonstração',money(total),'Período apresentado','wallet')}${metric('Membros',members.length,'Contas de membro','users')}${metric('Conversão de leads',`${state.admin.leads.length?number(converted/state.admin.leads.length*100):0}<small>%</small>`,`${converted} leads convertidos`,'trend')}${metric('Reservas de aulas',state.classes.reduce((n,c)=>n+c.booked,0),'Total de lugares reservados','calendar')}</div><section class="panel">${panelTitle('Receita por mês','Valores simulados em euros')}${revenueChart()}</section><section class="panel vertical-space">${panelTitle('Distribuição de planos')}<div class="three-cols">${state.plans.map(p=>`<div><p class="small muted">${e(p.name)}</p><div class="metric-value">${members.filter(m=>m.plan===p.id).length}<small> membros</small></div></div>`).join('')}</div></section>`;}
function render(){if(!state){renderAuth();return;}route=location.hash.slice(1)||'dashboard';if(route==='main')route='dashboard';if(![...memberNav,...communityNav,...adminNav].some(x=>x[0]===route))route='dashboard';if(route.startsWith('admin')&&state.user.role!=='admin')route='dashboard';const admin=route.startsWith('admin'),u=state.user,unread=state.notices.filter(n=>!n.read).length;const nav=items=>items.map(([id,ic,label])=>`<button class="nav-link ${id==='my_plan'?'nav-plan':''} ${route===id?'active':''}" data-route="${id}" ${route===id?'aria-current="page"':''}>${icon(ic)}${label}${id==='notices'&&unread?`<span class="tag-count">${unread}</span>`:''}</button>`).join('');const pages={dashboard,my_plan:myPlanPage,food:foodPage,classes:()=>classesPage(false),workout:workoutPage,progress:progressPage,checkin:checkinPage,shop:shopPage,account:accountPage,challenges:challengesPage,notices:()=>noticesPage(false),support:()=>supportPage(false),admin:adminOverview,'admin-members':adminMembers,'admin-leads':adminLeads,'admin-access':adminAccess,'admin-staff':adminStaff,'admin-classes':()=>classesPage(true),'admin-reports':adminReports,'admin-notices':()=>noticesPage(true),'admin-support':()=>supportPage(true)};$('#app').innerHTML=`<div class="overlay" data-action="menu"></div><aside class="sidebar" aria-label="Menu principal"><a class="brand" href="#${admin?'admin':'dashboard'}"><span class="brand-mark">S</span><span class="brand-name">STRONG<span>GYM</span></span></a><div class="nav-label">${admin?'ADMINISTRAÇÃO':'O TEU GINÁSIO'}</div><nav class="nav-list">${nav(admin?adminNav:memberNav)}</nav>${!admin?`<div class="nav-label">MAIS FORTES, JUNTOS</div><nav class="nav-list">${nav(communityNav)}${installButton()}</nav>`:''}<div class="sidebar-bottom"><div class="membership-mini"><span class="eyebrow">${admin?'STRONGGYM MANAGEMENT':'O TEU COMPROMISSO CONTA'}</span><strong>${admin?'Uma equipa. Mais força.':'O próximo nível é teu.'}</strong><p style="font-size:14px;color:#9e82a4">${admin?'Tudo o que precisas, num só lugar.':'Continua a investir em ti.'}</p><button data-route="${admin?'admin-reports':'account'}">${admin?'Ver indicadores':'Gerir a minha assinatura'}${icon('arrow')}</button></div><div class="sidebar-foot"><span class="dot"></span>STRONGGYM · LISBOA</div></div></aside><div class="shell"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Abrir menu">${icon('menu')}</button><span class="topbar-location">${icon('pin')}StrongGym Lisboa${icon('down')}</span><span class="topbar-spacer"></span><span class="occupancy-pill"><i class="dot"></i>${state.occupancy.current} pessoas a treinar</span>${isDemo||u.role==='admin'?`<select class="mode-select" aria-label="Área da aplicação" id="mode"><option value="member" ${!admin?'selected':''}>${isDemo?'Demo · ':''}Membro</option><option value="admin" ${admin?'selected':''}>${isDemo?'Demo · ':''}Administração</option></select>`:''}<span class="header-divider"></span>${prefToggles()}<button class="icon-btn" data-action="search" aria-label="Pesquisar na aplicação">${icon('search')}</button><button class="icon-btn" data-route="${admin?'admin-notices':'notices'}" aria-label="Notificações${unread?', '+unread+' por ler':''}">${icon('bell')}${unread?'<i class="notice-dot"></i>':''}</button><span class="header-divider"></span><button class="profile-btn" data-route="account"><span class="avatar">${e(initials(u.name))}</span><span><span class="profile-name">${e(u.name)}</span><span class="profile-plan">${admin?'Administrador':'Membro '+e(state.plans.find(p=>p.id===u.plan)?.name||'StrongGym')}</span></span>${icon('down')}</button></header><main id="main" class="content" tabindex="-1">${(pages[route]||dashboard)()}<footer class="dashboard-footer"><span>© ${new Date().getFullYear()} <span class="footer-brand">STRONGGYM</span> · Mais forte, todos os dias.</span>${isDemo?`<span class="demo-note">${icon('info')}Demonstração · dados guardados neste navegador</span>`:'<span>O teu espaço. O teu ritmo.</span>'}</footer></main></div>${!admin?bottomNav():''}`;document.body.classList.toggle('has-bottom-nav',!admin);document.title=SG.t(admin?'Administração':([...memberNav,...communityNav].find(n=>n[0]===route)||[])[2]||'StrongGym')+' · StrongGym';}
function renderAuth(){document.body.classList.remove('has-bottom-nav');const register=authMode==='register';$('#app').innerHTML=`<div class="login-shell"><div class="login-prefs">${prefToggles()}</div><section class="login-story"><div class="brand"><span class="brand-mark">S</span><span class="brand-name">STRONG<span>GYM</span></span></div><div><h1>Mais forte.<br>Todos os<br><span>dias.</span></h1><p>O teu treino, a tua evolução e a tua comunidade. Tudo num só lugar.</p></div><small>STRONGGYM TRAINING CLUB · LISBOA</small></section><section class="login-form-area"><form class="login-form" data-form="${register?'register':'login'}"><h2>${register?'O teu próximo nível começa aqui.':'Bom ter-te de volta.'}</h2><p>${register?'Cria a tua conta e começa a construir a tua melhor versão.':'Entra na tua conta para continuares a tua evolução.'}</p>${register?field('Nome completo','name','','text','required maxlength="100" autocomplete="name"'):''}${field('Email','email','','email','required autocomplete="username"')}${field('Palavra-passe','password','','password',`required minlength="12" maxlength="200" autocomplete="${register?'new-password':'current-password'}"`)}<div class="error-text" role="alert" id="auth-error"></div><button class="btn btn-primary" type="submit">${register?'Criar conta':'Entrar na StrongGym'}${icon('arrow')}</button>${installButton('btn btn-outline login-install')}<button class="link-btn" type="button" data-action="auth-mode">${register?'Já és membro? Entra aqui.':'Ainda não tens conta? Regista-te.'}</button></form></section></div>`;}
function progressModal(){modal('Regista a tua evolução','<p class="modal-subtitle">Uma medição por dia. Ao escolheres uma data já registada, atualizas essa medição.</p>'+form(field('Data','date',today(),'date',`required max="${today()}"`)+field('Peso (kg)','weight','','number','required min="20" max="400" step="0.1"')+field('Massa gorda (%)','bodyFat','','number','required min="1" max="70" step="0.1"')+field('Perímetro abdominal (cm)','waist','','number','required min="30" max="250" step="0.1"'),'progress.add','Guardar métricas'));}
function cartModal(){const items=cart.map(i=>({...i,product:state.products.find(p=>p.id===i.id)})).filter(i=>i.product);modal('Os teus próximos essenciais',`<p class="modal-subtitle">Carrinho de demonstração. Sem cobrança ou entrega real.</p>${items.map(i=>`<div class="cart-row"><strong>${e(i.product.name)}<small>${money(i.product.price)} / unidade</small></strong><div class="cart-qty"><button data-action="cart-minus" data-id="${e(i.id)}" aria-label="Retirar uma unidade de ${e(i.product.name)}">−</button><span>${i.qty}</span><button data-action="cart-plus" data-id="${e(i.id)}" aria-label="Adicionar uma unidade de ${e(i.product.name)}">+</button></div><span class="small">${money(i.qty*i.product.price)}</span></div>`).join('')||empty('O carrinho ainda está vazio','Escolhe os teus essenciais na loja.','bag')}${items.length?`<div class="cart-total"><span>Total</span><strong>${money(items.reduce((n,i)=>n+Math.round(i.product.price*100)*i.qty,0)/100)}</strong></div><div class="form-actions">${button('Concluir compra de demonstração','checkout','',true,'check')}</div>`:''}`);}
function assignPlanModal(id){const member=state.admin.members.find(m=>m.id===id);modal('Um plano à medida',`<p class="modal-subtitle">Personalizar o treino de <strong>${e(member.name)}</strong>.</p>${form(field('Nome do plano','title',SG.t('Treino A · Corpo inteiro'),'text','required maxlength="120"',true)+field('Objetivo e duração','subtitle',SG.t('Condição física · 45 min'),'text','required maxlength="200"',true)+textField('Exercícios — um por linha: nome | séries | repetições | descanso','exercises',SG.L('Agachamento | 3 | 12 | 60 s\nRemada | 3 | 12 | 60 s\nPrancha | 3 | 30 s | 45 s','Squat | 3 | 12 | 60 s\nRow | 3 | 12 | 60 s\nPlank | 3 | 30 s | 45 s'),'required maxlength="5000"'),'admin.plan.assign','Atribuir plano',`data-member-id="${e(id)}"`)}`);}
function classModal(){modal('Mais energia na agenda',form(field('Nome da aula','title','','text','required maxlength="100"',true)+selectField('Modalidade','category',['HIIT','Yoga','Cycling','Funcional','Pilates','Musculação'])+field('Instrutor','trainer','','text','required maxlength="100"')+field('Data','date',today(),'date',`required min="${today()}"`)+field('Hora de início','time','18:30','time','required')+field('Duração (minutos)','duration','45','number','required min="10" max="240"')+field('Capacidade','capacity','20','number','required min="1" max="200"')+field('Sala','room',SG.t('Estúdio 01'),'text','required maxlength="100"',true),'admin.class.add','Criar aula'));}
function searchModal(){modal('O que procuras?',`<label class="field">Pesquisar páginas<input id="global-search" type="search" placeholder="Treinos, aulas, loja…" autocomplete="off"></label><div id="search-results" class="modal-search-results"></div>`);searchResults('');$('#global-search').focus();}
function searchResults(q){const items=route.startsWith('admin')?adminNav:[...memberNav,...communityNav],query=q.toLocaleLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');$('#search-results').innerHTML=items.filter(x=>(x[2]+' '+SG.t(x[2])).toLocaleLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(query)).map(([id,ic,label])=>`<button class="search-result" data-route="${id}">${icon(ic)}${label}${icon('arrow')}</button>`).join('')||'<p class="small muted">Nenhuma página encontrada.</p>';}
async function enableNotifications(){if(!('Notification'in window)||!('serviceWorker'in navigator)){toast('Este navegador não suporta notificações.',true);return;}const permission=await Notification.requestPermission();if(permission==='granted'){await navigator.serviceWorker.register('./sw.js');localStorage.setItem('stronggym-notifications','on');const sw=await navigator.serviceWorker.ready;await sw.showNotification('StrongGym',{body:'Notificações ativas enquanto a aplicação está aberta.',icon:'./favicon.svg',tag:'stronggym-enabled'});toast('Notificações ativadas neste navegador.');}else toast('As notificações não foram autorizadas. Podes continuar a consultar os avisos.');}
function exportReport(){const rows=[[SG.t('Relatório StrongGym — valores de demonstração')],[SG.t('Mês'),SG.t('Receita simulada (EUR)')],...state.admin.revenue.map(r=>[SG.t(r.month),r.value]),[],[SG.t('Plano'),SG.t('Membros')],...state.plans.map(p=>[p.name,state.admin.members.filter(m=>m.plan===p.id&&m.role!=='admin').length])];const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=SG.L('stronggym-relatorio-','stronggym-report-')+today()+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Relatório CSV exportado.');}
document.addEventListener('click',async ev=>{
 const el=ev.target.closest('[data-action],[data-route]');if(!el||el.disabled)return;
 if(el.dataset.route){navigate(el.dataset.route);return;}
 const action=el.dataset.action,id=el.dataset.id;
 try{switch(action){
 case'toggle-lang':SG.setLang(SG.lang==='en'?'pt':'en');rerender();break;
 case'toggle-theme':SG.setTheme(SG.theme==='light'?'dark':'light');rerender();break;
 case'mp-example':case'mp-edit-data':case'mp-edit-goal':case'mp-edit-place':case'mp-print':mpHandleAction(action,el);break;
 case'fd-add':case'fd-clear-photo':case'fd-new':case'fd-delete':case'fd-save':await fdHandleAction(action,el);break;
 case'install-help':await installHelp();break;
 case'install-app':if(installPrompt){installPrompt.prompt();const choice=await installPrompt.userChoice;installPrompt=null;if(choice.outcome!=='accepted')render();}break;
 case'menu':$('.sidebar')?.classList.toggle('open');$('.overlay')?.classList.toggle('open');break;
 case'close-modal':closeModal();break;
 case'go-checkin':navigate('checkin');break;
 case'go-workout':navigate('my_plan');break;
 case'new-progress':progressModal();break;
 case'book-class':el.disabled=true;await mutate('class.book',{id});break;
 case'cancel-class':modal('Libertar o teu lugar?',`<div class="modal-confirm"><p>A tua reserva em <strong>${e(state.classes.find(c=>c.id===id)?.title)}</strong> será cancelada e o lugar fica disponível para outro membro.</p><div class="form-actions">${button('Manter reserva','close-modal')}${button('Cancelar reserva','confirm-cancel',`data-id="${e(id)}"`,true)}</div></div>`);break;
 case'confirm-cancel':await mutate('class.cancel',{id});break;
 case'class-view':classView=classView==='agenda'?'bookings':'agenda';render();break;
 case'week-prev':case'week-next':{const d=new Date(calendarStart+'T12:00:00');d.setDate(d.getDate()+(action==='week-next'?7:-7));calendarStart=d.toLocaleDateString('en-CA');selectedDay=calendarStart;classView='agenda';render();break;}
 case'select-day':selectedDay=el.dataset.day;classView='agenda';render();break;
 case'class-filter':classCategory=el.dataset.category;render();break;
 case'toggle-checkin':el.disabled=true;await mutate('checkin.toggle');break;
 case'finish-workout':if(exerciseChecks.size<state.workout.exercises.length){toast('Marca os exercícios concluídos antes de terminares o treino.');break;}if(await mutate('workout.complete'))exerciseChecks.clear();break;
 case'change-plan':{const p=state.plans.find(x=>x.id===id);modal('O teu próximo plano',`<div class="modal-confirm"><p>Alterar a assinatura para <strong>${e(p.name)}</strong>, por <strong>${money(p.price)}/mês</strong>?</p><div class="notice-box vertical-space">Esta é uma alteração de demonstração. Não será efetuada nenhuma cobrança.</div><div class="form-actions">${button('Voltar','close-modal')}${button('Confirmar alteração','confirm-plan',`data-id="${e(id)}"`,true)}</div></div>`);break;}
 case'confirm-plan':await mutate('subscription.change',{plan:id});break;
 case'add-cart':case'cart-plus':{const p=state.products.find(x=>x.id===id),i=cart.find(x=>x.id===id);if((i?.qty||0)>=p.stock){toast('A quantidade atingiu o stock disponível.',true);break;}if(i)i.qty++;else cart.push({id,qty:1});checkoutKey=crypto.randomUUID();if(action==='cart-plus'){closeModal();cartModal();}else{toast('Adicionado ao carrinho.');render();}break;}
 case'cart-minus':{const i=cart.find(x=>x.id===id);if(i)i.qty--;cart=cart.filter(x=>x.qty>0);checkoutKey=crypto.randomUUID();closeModal();cartModal();break;}
 case'cart':cartModal();break;
 case'checkout':el.disabled=true;if(await mutate('order.create',{items:cart,idempotencyKey:checkoutKey})){cart=[];checkoutKey=crypto.randomUUID();render();}break;
 case'join-challenge':await mutate('challenge.join',{id});break;
 case'enable-notifications':await enableNotifications();break;
 case'read-notices':await mutate('notifications.read');break;
 case'new-ticket':modal('Estamos aqui para ti',form(field('Assunto','subject','','text','required maxlength="150"',true)+textField('A tua mensagem','message','','required maxlength="5000"'),'ticket.create','Enviar pedido'));break;
 case'new-lead':modal('Uma nova oportunidade',form(field('Nome','name','','text','required maxlength="100"',true)+field('Email','email','','email','required maxlength="150"',true)+field('Interesse','interest','','text','required maxlength="200"',true),'admin.lead.add','Adicionar lead'));break;
 case'new-staff':modal('Dá as boas-vindas à equipa',form(field('Nome','name','','text','required maxlength="100"',true)+field('Email','email','','email','required maxlength="150"',true)+field('Função','role','','text','required maxlength="100"',true),'admin.staff.add','Adicionar funcionário'));break;
 case'new-shift':if(!state.admin.staff.length){toast('Adiciona primeiro um funcionário.');break;}modal('Organizar um novo turno',form(selectField('Funcionário','staffId',state.admin.staff.map(s=>[s.id,s.name]),'',true)+field('Data','date',today(),'date','required',true)+field('Entrada','start','09:00','time','required')+field('Saída','end','17:00','time','required'),'admin.shift.add','Criar turno'));break;
 case'new-notice':modal('Uma mensagem para todos',form(field('Título','title','','text','required maxlength="150"',true)+textField('Mensagem','body','','required maxlength="5000"'),'admin.notice.add','Publicar aviso'));break;
 case'reply-ticket':{const t=state.admin.tickets.find(t=>t.id===id);modal('Responder ao membro',`<p class="modal-subtitle">${e(t.subject)}</p>${form(textField('Resposta da equipa','reply',t.reply||'','required maxlength="5000"'),'admin.ticket.reply','Enviar resposta',`data-id="${e(id)}"`)}`);break;}
 case'assign-plan':assignPlanModal(id);break;
 case'new-class':classModal();break;
 case'admin-exit':await mutate('admin.access.exit',{id});break;
 case'export-report':exportReport();break;
 case'search':searchModal();break;
 case'auth-mode':authMode=authMode==='login'?'register':'login';renderAuth();break;
 case'logout':await api.request('/api/logout',{});resetTransient();resetTransient();state=null;clearInterval(pollTimer);renderAuth();break;
 }}catch(error){toast(error.message,true);}finally{if(el.isConnected)el.disabled=false;}
});
document.addEventListener('change',async ev=>{
 const el=ev.target;
 if(el.classList.contains('fd-file')){fdHandleFile(el);return;}
 if(el.id==='mp-override'){mpOverride(el.value);return;}
 if(el.id==='agenda-date'&&el.value){selectedDay=el.value;calendarStart=el.value;classView='agenda';render();}
 if(el.id==='mode'){if(isDemo)state=StrongGymDemo.role(el.value==='admin'?'admin':'member');navigate(el.value==='admin'?'admin':'dashboard');}
 if(el.dataset.exercise!==undefined){const n=Number(el.dataset.exercise);if(el.checked)exerciseChecks.add(n);else exerciseChecks.delete(n);render();}
 if(el.dataset.lead){const success=await mutate('admin.lead.update',{id:el.dataset.lead,stage:el.value});if(!success)render();}
});
document.addEventListener('input',ev=>{if(ev.target.id==='global-search')searchResults(ev.target.value);if(ev.target.id==='fd-text')FD.text=ev.target.value;if(ev.target.id==='mp-goal'){const prev=$('#mp-preview');if(prev)prev.innerHTML=mpPreview(ev.target.value,mpLoad().profile||{},mpWhere(mpLoad()));}});
document.addEventListener('submit',async ev=>{
 const f=ev.target;if(!f.matches('form[data-form]'))return;ev.preventDefault();const action=f.dataset.form,p=Object.fromEntries(new FormData(f));const submit=f.querySelector('[type="submit"]');submit.disabled=true;
 try{
  if(action==='food.analyse'){fdHandleSubmit(p);return;}
  if(action.startsWith('myplan.')){mpHandleSubmit(action,p,f);return;}
  if(action==='login'||action==='register'){await api.request('/api/'+action,p);resetTransient();state=await api.load();authMode='login';navigate(state.user.role==='admin'?'admin':'dashboard');render();startPolling();return;}
  if(action==='progress.add')for(const k of ['weight','bodyFat','waist'])p[k]=Number(p[k]);
  if(action==='admin.class.add'){p.capacity=Number(p.capacity);p.duration=Number(p.duration);}
  if(action==='admin.ticket.reply')p.id=f.dataset.id;
  if(action==='admin.plan.assign'){p.memberId=f.dataset.memberId;p.exercises=p.exercises.split('\n').filter(l=>l.trim()).map(line=>{const v=line.split('|').map(s=>s.trim());if(v.length!==4||!Number.isInteger(Number(v[1]))||Number(v[1])<1||Number(v[1])>20||!v[0]||!v[2]||!v[3])throw new Error('Usa: nome | séries (1–20) | repetições | descanso, em cada linha.');return {name:v[0],sets:Number(v[1]),reps:v[2],rest:v[3]};});}
  const saved=await mutate(action,p);if(saved&&action==='admin.class.add'){selectedDay=p.date;calendarStart=p.date;classView='agenda';render();}
 }catch(error){if($('#auth-error'))$('#auth-error').textContent=error.message;else toast(error.message,true);}finally{if(submit.isConnected)submit.disabled=false;}
});
$('#modal').addEventListener('click',ev=>{if(ev.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)closeModal();}});
window.addEventListener('hashchange',()=>{if(state){render();window.scrollTo({top:0,behavior:'instant'});}});
function startPolling(){clearInterval(pollTimer);if(isDemo)return;pollTimer=setInterval(async()=>{if(!state)return;try{const next=await api.load(),seen=new Set(state.notices.map(n=>n.id)),fresh=next.notices.filter(n=>!seen.has(n.id));state=next;if(fresh.length&&localStorage.getItem('stronggym-notifications')==='on'&&'Notification'in window&&Notification.permission==='granted'){const sw=await navigator.serviceWorker.ready;for(const n of fresh)await sw.showNotification(n.title,{body:n.body,tag:n.id,icon:'./favicon.svg'});}if(['dashboard','admin','admin-access','notices','admin-notices'].includes(route)&&!$('#modal').open&&!busy)render();}catch(error){if(error.status===401){resetTransient();state=null;clearInterval(pollTimer);renderAuth();}}},30000);}
(async()=>{try{state=isDemo?await StrongGymDemo.init():await api.load();render();startPolling();}catch(error){if(error.status===401){state=null;renderAuth();}else{const offline=!isDemo&&error instanceof TypeError;$('#app').innerHTML=offline?`<div class="loading"><span class="brand-mark">S</span><h2>${SG.L('Sem ligação ao servidor StrongGym.','No connection to the StrongGym server.')}</h2><p class="muted" style="max-width:460px;margin:0 auto">${navigator.onLine===false?SG.L('O dispositivo está sem internet. Liga-te a uma rede e tenta novamente.','This device is offline. Connect to a network and try again.'):SG.L('O servidor não está a responder. No computador, inicia-o com <b>Iniciar_StrongGym.bat</b> ou <b>python server.py --demo</b> e mantém a janela do terminal aberta.','The server is not responding. On the computer, start it with <b>Iniciar_StrongGym.bat</b> or <b>python server.py --demo</b> and keep the terminal window open.')}</p><button class="btn btn-primary" id="retry">${SG.L('Tentar novamente','Try again')}</button></div>`:`<div class="loading"><span class="brand-mark">S</span><h2>Não foi possível iniciar a aplicação.</h2><p class="muted">${e(error.message)}</p><button class="btn" id="retry">Tentar novamente</button></div>`;$('#retry').onclick=()=>location.reload();}}})();
startLiveReload();
